<?php require_once __DIR__.'/auth.php'; require_once __DIR__.'/layout.php'; $employee=current_employee($conn); if(!$employee){header('Location: logout.php');exit;} $stmt=$conn->prepare("SELECT payroll_id,period_start,period_end,basic_salary,allowances,other_earnings,deductions,gross_pay,net_pay,status FROM payroll_records WHERE employee_id=? AND status IN ('Approved','Paid') ORDER BY period_end DESC, payroll_id DESC"); $stmt->bind_param('i',$employee['employee_id']); $stmt->execute(); $rows=$stmt->get_result(); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<!-- FAVICON: Put your favicon file at /assets/favicon.png -->
<link rel="icon" type="image/png" href="../assets/favicon.png"><title>LCC Payroll System</title><link rel="stylesheet" href="../assets/css/app.css?v=20260909-rail4"><link rel="stylesheet" href="../assets/css/employee.css"><link rel="stylesheet" href="../assets/css/apple-system.css?v=20260916-apple9"><script src="../assets/js/app.js?v=20260916-rail5" defer></script><script src="../assets/js/apple-motion.js?v=20260916-apple1" defer></script></head><body><div class="app"><?php employee_sidebar('payroll'); ?><main class="main"><?php employee_topbar('My Payroll'); ?><div class="content"><div class="page-heading"><div><div class="eyebrow">EMPLOYEE PORTAL</div><h1>My Payroll</h1><p>Only payroll records belonging to your employee account are shown here.</p></div></div><section class="card"><div class="card-head"><div><h2>Payroll History</h2><p>View your available payroll periods and payroll breakdown.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Pay Period</th><th>Gross Pay</th><th>Deductions</th><th>Net Pay</th><th>Status</th><th></th></tr></thead><tbody><?php if($rows->num_rows===0): ?><tr><td colspan="6" class="empty">No payroll records available yet.</td></tr><?php else: while($r=$rows->fetch_assoc()): ?><tr><td><?php echo e(date('M d, Y',strtotime($r['period_start'])).' – '.date('M d, Y',strtotime($r['period_end']))); ?></td><td><?php echo money($r['gross_pay']); ?></td><td><?php echo money($r['deductions']); ?></td><td><strong><?php echo money($r['net_pay']); ?></strong></td><td><span class="badge"><?php echo e($r['status']); ?></span></td><td><a class="btn btn-secondary btn-small" target="_blank" rel="noopener" href="../print/payroll.php?id=<?php echo (int)$r['payroll_id']; ?>">Print</a></td></tr><?php endwhile; endif; ?></tbody></table></div></section></div></main></div></body></html>
